import table from "./chainTable.json" with { type: "json" };

/**
 * Chain registry for display (tools pages, MCP copy, counts): blocktools chainTable() rows plus zec, as listChains()
 * does. Generated by apps/api/scripts/gen-chain-table.cjs; apps/api/src/blocktools.chaintable.test.ts fails on drift.
 * Metadata only: signing, verify, sweep and fee logic never read this.
 */
export type ChainRow = {
  name: string;
  ticker: string;
  title: string;
  /** null when the chain has no SLIP-44 entry (wdc, anc) */
  coin_type: number | null;
  curve: string;
  encoding: string;
  native_seed: boolean;
  sign: string;
  buildable: boolean;
  verified: boolean;
  source: string;
};
export const CHAIN_TABLE: readonly ChainRow[] = table;
export const CHAIN_COUNT = CHAIN_TABLE.length;
/** Bitcoin-family rows (Base58 version bytes / bech32 / WIF) */
export const UTXO_CHAIN_COUNT = CHAIN_TABLE.filter((c) => c.encoding === "utxo").length;
export const ACCOUNT_CHAIN_COUNT = CHAIN_COUNT - UTXO_CHAIN_COUNT;
